//! Payroll parity beyond PPh 21: BPJS shares, overtime, THR, absence.
//!
//! Fixtures are generated by `scripts/parity_export.py` from the Python oracle.
//! Each test rebuilds the statutory tables (Rust key names where they differ
//! from Python: `hours_per_month`/`first_tier`/`rest_tier`) and asserts the
//! public `compute_monthly_line` / `compute_thr_line` APIs reproduce the
//! Python sen values exactly.

use hragents_core::ids::{EmployeeId, RateTableId};
use hragents_core::money::Money;
use hragents_core::payroll::{
    RateEntry, RateTable, RateTableKind, RateTableSet, compute_monthly_line, compute_thr_line,
};
use hragents_core::people::Employee;
use hragents_core::time::{BusinessDate, UtcInstant};
use serde::Deserialize;

// ---------- fixture shapes ----------

#[derive(Deserialize)]
struct BpjsFile {
    shares: Vec<BpjsShare>,
    lines: Vec<BpjsLine>,
}

#[derive(Deserialize)]
struct BpjsShare {
    #[allow(dead_code)]
    name: String,
    #[allow(dead_code)]
    sen: i64,
}

#[derive(Deserialize)]
struct BpjsLine {
    name: String,
    base_salary: String,
    fixed_allowances: String,
    working_days: u32,
    jp_wage_cap: Option<String>,
    kes_employee_sen: i64,
    kes_employer_sen: i64,
    jht_employee_sen: i64,
    jht_employer_sen: i64,
    jp_employee_sen: i64,
    jp_employer_sen: i64,
    jkk_employer_sen: i64,
    jkm_employer_sen: i64,
    gross_sen: i64,
    net_sen: i64,
    employer_cost_sen: i64,
}

#[derive(Deserialize)]
struct OvertimeCase {
    name: String,
    base_salary: String,
    fixed_allowances: String,
    working_days: u32,
    absence_days: u32,
    overtime_minutes: i64,
    overtime_pay_sen: i64,
    gross_sen: i64,
    net_sen: i64,
}

#[derive(Deserialize)]
struct ThrCase {
    name: String,
    base_salary: String,
    fixed_allowances: String,
    working_days: u32,
    absence_days: u32,
    service_months: u32,
    thr_months: i64,
    thr_pay_sen: i64,
    gross_sen: i64,
    net_sen: i64,
}

#[derive(Deserialize)]
struct AbsenceCase {
    name: String,
    base_salary: String,
    fixed_allowances: String,
    working_days: u32,
    absence_days: u32,
    base_paid_sen: i64,
    allowances_sen: i64,
    gross_sen: i64,
    net_sen: i64,
}

// ---------- table builders (mirror the export's illustrative values) ----------

fn day() -> BusinessDate {
    BusinessDate::parse("2026-11-01").unwrap()
}

fn now() -> UtcInstant {
    UtcInstant::from_millis(1_760_000_000_000).unwrap()
}

fn effective() -> BusinessDate {
    BusinessDate::parse("2026-01-01").unwrap()
}

fn table(kind: RateTableKind, entries: Vec<RateEntry>) -> RateTable {
    RateTable {
        id: RateTableId::new(),
        kind,
        effective_from: effective(),
        effective_to: None,
        verified: true,
        verified_by: Some("parity".into()),
        verified_at: Some(now()),
        source_note: Some("parity fixture (illustrative)".into()),
        entries,
    }
}

fn shares_entry(
    key: Option<&str>,
    employee_bp: i64,
    employer_bp: i64,
    wage_cap: Option<Money>,
) -> RateEntry {
    RateEntry {
        key: key.map(str::to_owned),
        employee_share_bp: employee_bp,
        employer_share_bp: employer_bp,
        wage_cap,
        flat_amount: None,
        multiplier_bp: None,
        lower_bound: None,
        upper_bound: None,
        hours_per_month: None,
        note: None,
    }
}

fn monthly_tables(jp_cap: Option<Money>) -> RateTableSet {
    let mut set = RateTableSet::default();
    set.insert(table(
        RateTableKind::BpjsKesehatan,
        vec![shares_entry(None, 100, 400, None)],
    ));
    set.insert(table(
        RateTableKind::BpjsKetenagakerjaanJht,
        vec![shares_entry(Some("normal"), 200, 370, None)],
    ));
    set.insert(table(
        RateTableKind::BpjsKetenagakerjaanJp,
        vec![shares_entry(None, 100, 200, jp_cap)],
    ));
    set.insert(table(
        RateTableKind::BpjsJkk,
        vec![shares_entry(Some("class_1"), 0, 24, None)],
    ));
    set.insert(table(
        RateTableKind::BpjsJkm,
        vec![shares_entry(None, 0, 30, None)],
    ));
    set.insert(table(
        RateTableKind::OvertimePremium,
        vec![
            RateEntry {
                key: Some("hours_per_month".into()),
                employee_share_bp: 0,
                employer_share_bp: 0,
                wage_cap: None,
                flat_amount: None,
                multiplier_bp: None,
                lower_bound: None,
                upper_bound: None,
                hours_per_month: Some(173),
                note: None,
            },
            RateEntry {
                key: Some("first_tier".into()),
                employee_share_bp: 0,
                employer_share_bp: 0,
                wage_cap: None,
                flat_amount: None,
                multiplier_bp: Some(15_000),
                lower_bound: None,
                upper_bound: None,
                hours_per_month: None,
                note: None,
            },
            RateEntry {
                key: Some("rest_tier".into()),
                employee_share_bp: 0,
                employer_share_bp: 0,
                wage_cap: None,
                flat_amount: None,
                multiplier_bp: Some(20_000),
                lower_bound: None,
                upper_bound: None,
                hours_per_month: None,
                note: None,
            },
        ],
    ));
    set.insert(table(
        RateTableKind::Pph21Ptkp,
        vec![
            RateEntry::flat(Some("personal"), Money::from_rupiah(54_000_000).unwrap()),
            RateEntry::flat(Some("dependent"), Money::from_rupiah(4_500_000).unwrap()),
        ],
    ));
    set.insert(table(
        RateTableKind::Pph21Ter,
        vec![
            RateEntry {
                key: None,
                employee_share_bp: 50,
                employer_share_bp: 0,
                wage_cap: None,
                flat_amount: None,
                multiplier_bp: None,
                lower_bound: Some(Money::from_rupiah(0).unwrap()),
                upper_bound: Some(Money::from_rupiah(10_000_000).unwrap()),
                hours_per_month: None,
                note: None,
            },
            RateEntry {
                key: None,
                employee_share_bp: 100,
                employer_share_bp: 0,
                wage_cap: None,
                flat_amount: None,
                multiplier_bp: None,
                lower_bound: Some(Money::from_rupiah(10_000_000).unwrap()),
                upper_bound: Some(Money::from_rupiah(100_000_000).unwrap()),
                hours_per_month: None,
                note: None,
            },
        ],
    ));
    set.insert(table(
        RateTableKind::MinimumWage,
        vec![RateEntry::flat(
            None,
            Money::from_rupiah(2_500_000).unwrap(),
        )],
    ));
    set
}

fn thr_tables() -> RateTableSet {
    let mut set = monthly_tables(None);
    let entry = |key: &str, mult_bp: i64| RateEntry {
        key: Some(key.to_owned()),
        employee_share_bp: 0,
        employer_share_bp: 0,
        wage_cap: None,
        flat_amount: None,
        multiplier_bp: Some(mult_bp),
        lower_bound: None,
        upper_bound: None,
        hours_per_month: None,
        note: None,
    };
    set.insert(table(
        RateTableKind::ThrFormula,
        vec![
            entry("under_1y", 10_000),
            entry("1y", 20_000),
            entry("2y", 30_000),
            entry("8y_plus", 100_000),
        ],
    ));
    set
}

fn employee_for(input_id: EmployeeId) -> Employee {
    let mut employee = Employee::new(
        "E-001",
        "Parity",
        "Staff",
        "Product",
        BusinessDate::parse("2024-01-15").unwrap(),
        now(),
    );
    employee.id = input_id;
    employee.dependents = 0;
    employee.jkk_risk_class = Some(1);
    employee
}

fn monthly_input(
    id: EmployeeId,
    base: &str,
    fixed: &str,
    working_days: u32,
    absence_days: u32,
    overtime_minutes: i64,
    service_months: u32,
) -> hragents_core::payroll::PayrollInput {
    use hragents_core::payroll::PayrollInput;
    let mut input = PayrollInput::new(id, "Parity", Money::parse(base).unwrap());
    input.fixed_allowances = Money::parse(fixed).unwrap();
    input.working_days = working_days;
    input.absence_days = absence_days;
    input.overtime_minutes = overtime_minutes;
    input.service_months = service_months;
    input
}

// ---------- tests ----------

#[test]
fn bpjs_shares_match_python() {
    let files: Vec<BpjsFile> = serde_json::from_str(include_str!(
        "../../../../parity/fixtures/payroll_bpjs.json"
    ))
    .unwrap();
    assert_eq!(files.len(), 1);
    let file = &files[0];
    // Unit-level oracle values are documented in `shares`; the line totals
    // below are the share-equivalent assertion through the public API.
    assert!(!file.shares.is_empty());
    for line in &file.lines {
        let jp_cap = line
            .jp_wage_cap
            .as_deref()
            .map(|cap| Money::parse(cap).unwrap());
        let tables = monthly_tables(jp_cap);
        let id = EmployeeId::new();
        let input = monthly_input(
            id,
            &line.base_salary,
            &line.fixed_allowances,
            line.working_days,
            0,
            0,
            0,
        );
        let (computed, _) =
            compute_monthly_line(&input, Some(&employee_for(id)), &tables, day()).unwrap();
        assert_eq!(
            computed.bpjs_kesehatan_employee.sen(),
            line.kes_employee_sen,
            "case {} kes employee diverged",
            line.name
        );
        assert_eq!(
            computed.bpjs_kesehatan_employer.sen(),
            line.kes_employer_sen,
            "case {} kes employer diverged",
            line.name
        );
        assert_eq!(
            computed.bpjs_jht_employee.sen(),
            line.jht_employee_sen,
            "case {} jht employee diverged",
            line.name
        );
        assert_eq!(
            computed.bpjs_jht_employer.sen(),
            line.jht_employer_sen,
            "case {} jht employer diverged",
            line.name
        );
        assert_eq!(
            computed.bpjs_jp_employee.sen(),
            line.jp_employee_sen,
            "case {} jp employee diverged",
            line.name
        );
        assert_eq!(
            computed.bpjs_jp_employer.sen(),
            line.jp_employer_sen,
            "case {} jp employer diverged",
            line.name
        );
        assert_eq!(
            computed.bpjs_jkk_employer.sen(),
            line.jkk_employer_sen,
            "case {} jkk diverged",
            line.name
        );
        assert_eq!(
            computed.bpjs_jkm_employer.sen(),
            line.jkm_employer_sen,
            "case {} jkm diverged",
            line.name
        );
        assert_eq!(
            computed.gross.sen(),
            line.gross_sen,
            "case {} gross diverged",
            line.name
        );
        assert_eq!(
            computed.net.sen(),
            line.net_sen,
            "case {} net diverged",
            line.name
        );
        assert_eq!(
            computed.employer_cost.sen(),
            line.employer_cost_sen,
            "case {} employer cost diverged",
            line.name
        );
    }
}

#[test]
fn overtime_matches_python() {
    let cases: Vec<OvertimeCase> = serde_json::from_str(include_str!(
        "../../../../parity/fixtures/payroll_overtime.json"
    ))
    .unwrap();
    assert!(!cases.is_empty());
    let tables = monthly_tables(None);
    for case in &cases {
        let id = EmployeeId::new();
        let input = monthly_input(
            id,
            &case.base_salary,
            &case.fixed_allowances,
            case.working_days,
            case.absence_days,
            case.overtime_minutes,
            0,
        );
        let (computed, _) =
            compute_monthly_line(&input, Some(&employee_for(id)), &tables, day()).unwrap();
        assert_eq!(
            computed.overtime_pay.sen(),
            case.overtime_pay_sen,
            "case {} overtime pay diverged",
            case.name
        );
        assert_eq!(
            computed.gross.sen(),
            case.gross_sen,
            "case {} gross diverged",
            case.name
        );
        assert_eq!(
            computed.net.sen(),
            case.net_sen,
            "case {} net diverged",
            case.name
        );
    }
}

#[test]
fn thr_ladder_matches_python() {
    let cases: Vec<ThrCase> =
        serde_json::from_str(include_str!("../../../../parity/fixtures/payroll_thr.json")).unwrap();
    assert!(!cases.is_empty());
    let tables = thr_tables();
    for case in &cases {
        let id = EmployeeId::new();
        let input = monthly_input(
            id,
            &case.base_salary,
            &case.fixed_allowances,
            case.working_days,
            case.absence_days,
            0,
            case.service_months,
        );
        let (computed, _) =
            compute_thr_line(&input, Some(&employee_for(id)), &tables, day()).unwrap();
        assert_eq!(
            computed.base_salary.sen(),
            case.thr_pay_sen,
            "case {} thr pay diverged",
            case.name
        );
        assert_eq!(
            computed.gross.sen(),
            case.gross_sen,
            "case {} gross diverged",
            case.name
        );
        assert_eq!(
            computed.net.sen(),
            case.net_sen,
            "case {} net diverged",
            case.name
        );
        assert_eq!(
            computed.thr_months_bp,
            Some(case.thr_months * 10_000),
            "case {} thr months diverged",
            case.name
        );
    }
}

#[test]
fn absence_proration_matches_python() {
    let cases: Vec<AbsenceCase> = serde_json::from_str(include_str!(
        "../../../../parity/fixtures/payroll_absence.json"
    ))
    .unwrap();
    assert!(!cases.is_empty());
    let tables = monthly_tables(None);
    for case in &cases {
        let id = EmployeeId::new();
        let input = monthly_input(
            id,
            &case.base_salary,
            &case.fixed_allowances,
            case.working_days,
            case.absence_days,
            0,
            0,
        );
        let (computed, _) =
            compute_monthly_line(&input, Some(&employee_for(id)), &tables, day()).unwrap();
        assert_eq!(
            computed.base_salary.sen(),
            case.base_paid_sen,
            "case {} base paid diverged",
            case.name
        );
        assert_eq!(
            computed.allowances.sen(),
            case.allowances_sen,
            "case {} allowances diverged",
            case.name
        );
        assert_eq!(
            computed.gross.sen(),
            case.gross_sen,
            "case {} gross diverged",
            case.name
        );
        assert_eq!(
            computed.net.sen(),
            case.net_sen,
            "case {} net diverged",
            case.name
        );
    }
}
